const $=s=>document.querySelector(s);
async function load(){let r=await chrome.runtime.sendMessage({type:'get'});if(r.error)throw Error(r.error);$('#enabled').checked=r.state.enabled;$('#exceptions').value=r.state.exceptions.join('\n');$('#status').textContent=(r.state.enabled?'ON — strict rule configured':'OFF — strict rule removed')+' · '+r.rules.length+' dynamic rule(s). Reload pages after changes.';}
$('#save').onclick=async()=>{try{let r=await chrome.runtime.sendMessage({type:'set',enabled:$('#enabled').checked,exceptions:$('#exceptions').value.split('\n')});if(r.error)throw Error(r.error);await load();$('#result').textContent='Applied. Reload affected pages.';}catch(e){$('#result').textContent='Error: '+e.message;}};
$('#reload').onclick=async()=>{let tabs=await chrome.tabs.query({});let n=0;for(let t of tabs){if(t.url?.startsWith('http://127.0.0.1:8879/')||t.url?.startsWith('https://v2.streameast.ga/')){await chrome.tabs.reload(t.id);n++;}}$('#result').textContent='Reload requested for '+n+' test page(s).';};load().catch(e=>$('#status').textContent=e.message);
